import React, { useEffect, useState } from "react";
import axios from "axios";
import "./global.css";

export default function SwapRequests() {
  const [requests, setRequests] = useState([]);
  const user = JSON.parse(localStorage.getItem("user") || "{}");

  useEffect(() => {
    if (!user || !user._id) return;
    axios
      .get(`http://localhost:5001/api/swaps/${user._id}`)
      .then((res) => setRequests(res.data))
      .catch((err) => console.log(err));
  }, [user]);

  const handleAccept = async (id) => {
    try {
      await axios.post(`http://localhost:5001/api/swaps/accept/${id}`);
      alert("Swap accepted!");
      setRequests((prev) => prev.map(r => r._id === id ? {...r, status: "accepted"} : r));
    } catch (err) {
      alert("Action failed");
    }
  };

  const handleReject = async (id) => {
    try {
      await axios.post(`http://localhost:5001/api/swaps/reject/${id}`);
      alert("Swap rejected!");
      setRequests((prev) => prev.map(r => r._id === id ? {...r, status: "rejected"} : r));
    } catch (err) {
      alert("Action failed");
    }
  };

  return (
    <div style={{ padding: 30 }}>
      <h1>Swap Requests</h1>

      {requests.length === 0 ? (
        <p>No swap requests yet.</p>
      ) : (
        requests.map((r) => (
          <div
            key={r._id}
            style={{
              padding: 20,
              border: "1px solid #ddd",
              marginBottom: 10,
              borderRadius: 8,
            }}
          >
            <h3>Request from: <b>{r.requestedByName}</b></h3>
            <p>Wants your: <b>{r.productWantedTitle}</b></p>
            <p>Offered: <b>{r.offeredProductTitle}</b></p>
            <p>Status: <b>{r.status}</b></p>

            {r.status === "pending" && (
              <>
                <button
                  onClick={() => handleAccept(r._id)}
                  style={{
                    marginRight: 10,
                    padding: "8px 15px",
                    background: "#1aaf5d",
                    color: "white",
                    border: "none",
                    borderRadius: 6,
                  }}
                >
                  Accept
                </button>

                <button
                  onClick={() => handleReject(r._id)}
                  style={{
                    padding: "8px 15px",
                    background: "#ff4747",
                    color: "white",
                    border: "none",
                    borderRadius: 6,
                  }}
                >
                  Reject
                </button>
              </>
            )}
          </div>
        ))
      )}
    </div>
  );
}
